function toNumbers(value: unknown): number[] {
    if (!Array.isArray(value)) throw new TypeError("massiv kutilgan")
    return value.map(v => {
        const n = Number(v)
        if (Number.isNaN(n)) throw new TypeError(`son emas: ${v}`)
        return n
    })
}
