type Product = { name: string; category: string; inStock: boolean; price: number }

const products: Product[] = [
    { name: "Noutbuk", category: "texnika", inStock: true, price: 9_000_000 },
    { name: "Sichqoncha", category: "texnika", inStock: false, price: 120_000 },
    { name: "Stol", category: "mebel", inStock: true, price: 1_500_000 },
    { name: "Stul", category: "mebel", inStock: true, price: 400_000 },
]

// Foydalanuvchi tanlagan filtrlar: faqat berilgan maydonlar tekshiriladi
function search(items: Product[], criteria: Partial<Pick<Product, "category" | "inStock">>) {
    const checks = Object.entries(criteria) as [keyof Product, unknown][]
    return items.filter(p => checks.every(([key, value]) => p[key] === value))
}

console.log(search(products, { category: "mebel" }).map(p => p.name))
console.log(search(products, { category: "texnika", inStock: true }).map(p => p.name))
