type State = "yangi" | "to'lanmoqda" | "to'landi" | "bekor"
type Event = "pay" | "approve" | "cancel"
type Transition = [from: State, event: Event, to: State]

const transitions: Transition[] = [
    ["yangi", "pay", "to'lanmoqda"],
    ["to'lanmoqda", "approve", "to'landi"],
    ["yangi", "cancel", "bekor"],
    ["to'lanmoqda", "cancel", "bekor"],
]

function next(state: State, event: Event): State {
    const found = transitions.find(([from, ev]) => from === state && ev === event)
    return found ? found[2] : state       // mos o'tish yo'q — holat o'zgarmaydi
}

let state: State = "yangi"
for (const ev of ["pay", "approve", "cancel"] as const) {
    state = next(state, ev)
    console.log(ev, "→", state)
}

