class BiMap<K, V> {
    private fwd = new Map<K, V>(); private back = new Map<V, K>()
    set(k: K, v: V) { this.fwd.set(k, v); this.back.set(v, k); return this }
    get(k: K) { return this.fwd.get(k) }
    keyOf(v: V) { return this.back.get(v) }
}
