type User = { id: number; name: string; email: string; active: boolean }
const users: User[] = [
    { id: 1, name: "Ali", email: "ali@mail.uz", active: true },
    { id: 2, name: "Bek", email: "bek@mail.uz", active: true },
]

// Parametr naqshi: id ni ajratib, qolgan maydonlarni "patch" sifatida yig'amiz
function updateUser({ id, ...changes }: Partial<User> & { id: number }): User[] {
    return users.map(u => (u.id === id ? { ...u, ...changes } : u))
}

