function sum(xs: readonly number[]): number {
    if (xs.length === 0) return 0                // bo'sh massiv — rekursiya tugaydi
    const [head, ...tail] = xs                   // birinchisi va qolganlari
    return head + sum(tail)
}
console.log(sum([1, 2, 3, 4]), sum([]))

function max(xs: readonly number[]): number | undefined {
    if (xs.length === 0) return undefined
    const [head, ...tail] = xs
    const restMax = max(tail)
    return restMax === undefined || head > restMax ? head : restMax
}
console.log(max([3, 9, 2]), max([]))

const reverse = <T,>(xs: readonly T[]): T[] => {
    if (xs.length === 0) return []
    const [head, ...tail] = xs
    return [...reverse(tail), head]
}
console.log(reverse(["a", "b", "c"]))

type Ok<T> = { ok: true; value: T }
type Err = { ok: false; error: string }
type Result<T> = Ok<T> | Err

function parseAge(input: string): Result<number> {
    const n = Number(input)
    return Number.isInteger(n) && n > 0 ? { ok: true, value: n } : { ok: false, error: `noto'g'ri yosh: "${input}"` }
}

for (const input of ["25", "abc", "-3"]) {
    const result = parseAge(input)
    if (result.ok) {
        const { value } = result              // toraytirishdan KEYIN ochamiz — value: number
        console.log("yosh:", value)
    } else {
        const { error } = result              // bu yerda faqat Err — error: string
        console.log(error)
    }
}

